using System;
using System.Collections.Generic;

namespace Fliqlo
{
    public static class WebAssets
    {
        private static readonly Dictionary<string, byte[]> _files = new Dictionary<string, byte[]>(StringComparer.OrdinalIgnoreCase);

        static WebAssets()
        {
            Register("index.html", "");
            Register("1.5/index.html", "");
            Register("fliqlo.min.css", "");
            Register("1.5/fliqlo.min.css", "");
            Register("fontfaceonload.js", "");
            Register("1.5/fontfaceonload.js", "");
            Register("jquery.min.js", "");
            Register("1.5/jquery.min.js", "");
            Register("fliqlo.min.js", "");
            Register("1.5/fliqlo.min.js", "");
            Register("fliqlo.woff", "");
            Register("1.5/fliqlo.woff", "");
            Register("fliqlo.ttf", "");
            Register("1.5/fliqlo.ttf", "");
            Register("fliqlo.eot", "");
            Register("1.5/fliqlo.eot", "");
        }

        private static void Register(string path, string base64)
        {
            _files[path] = Convert.FromBase64String(base64);
        }

        public static byte[] Get(string path)
        {
            byte[] data;
            if (_files.TryGetValue(path, out data))
                return data;
            return null;
        }
    }
}